const c=(key:string,label:string,min:number,max:number,step:number,value:number)=>({key,label,min,max,step,value});
const n=(v:number)=>String(Number(v.toFixed(3)));
export function routeCost(p:number,loss:number,expert:number){const fast=1+(1-p)*loss,deep=expert+.02*loss;return{fast,deep,chosen:Math.min(fast,deep),route:fast<=deep?"Fast path":"Deep path"}};
export const jobs=[{name:"Fix code",cost:4,gain:11},{name:"Review a table",cost:3,gain:8},{name:"Summarize a document",cost:2,gain:4},{name:"Check arithmetic",cost:5,gain:12},{name:"Classify a request",cost:1,gain:2}];
export function budgetSearch(budget:number){let best=0,chosen=0,used=0;for(let mask=0;mask<1<<jobs.length;mask++){let cost=0,gain=0;for(let i=0;i<jobs.length;i++)if(mask&(1<<i)){cost+=jobs[i].cost;gain+=jobs[i].gain}if(cost<=budget&&gain>best){best=gain;chosen=mask;used=cost}}return{best,used,names:jobs.filter((_,i)=>chosen&(1<<i)).map(j=>j.name)}};
export function memoryCost(age:number,tau:number,loss:number,refresh:number){const p=.98*Math.exp(-age/tau),reuse=.2+(1-p)*loss,fresh=refresh+.02*loss;return{p,reuse,fresh,chosen:Math.min(reuse,fresh),refresh: fresh<reuse}};
